// Normalize incoming jobs from Arbeitnow

return items.map(item => {
  const job = item.json;

  return {
    json: {
      source: "arbeitnow",
      external_id: job.slug,
      company: job.company_name,
      title: job.title,
      description: job.description,
      location: job.location,
      remote: job.remote,
      employment_types: job.job_types || [],
      tags: job.tags || [],
      url: job.url,
      posted_at: job.created_at,
      status: "new"
    }
  };
});

return items.map(item => {
  const job = item.json;

  let cleanDescription = job.description || "";

  // Decode HTML entities.
  // Run more than once because some values are double-encoded,
  // for example &amp;amp; -> &amp; -> &
  for (let i = 0; i < 3; i++) {
    cleanDescription = cleanDescription
      .replace(/&nbsp;/gi, " ")
      .replace(/&amp;/gi, "&")
      .replace(/&quot;/gi, '"')
      .replace(/&#39;/gi, "'")
      .replace(/&apos;/gi, "'")
      .replace(/&lt;/gi, "<")
      .replace(/&gt;/gi, ">");
  }

  // Remove HTML tags
  cleanDescription = cleanDescription
    .replace(/<[^>]*>/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  return {
    json: {
      ...job,
      clean_description: cleanDescription.slice(0, 8000)
    }
  };
});

// Parse AI Score
// Parse Qwen's response and enforce consistent score categories.

const rawResponse = $json.text || "";

// Get the original job currently being processed
const job = $("Loop Over Items").item.json;

// Remove Markdown formatting if Qwen returns ```json blocks
const raw = rawResponse
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/```$/i, "")
  .trim();

// Parse Qwen's JSON response
let score;

try {
  score = JSON.parse(raw);
} catch (error) {
  throw new Error(`Could not parse AI response: ${raw}`);
}

// Preserve Qwen's original decision
const llmDecision = score.decision;

// Keep the original numerical score
const fitScore = score.fit_score;

// Calculate the correct decision using our scoring thresholds
// Do not silently correct invalid or missing scores.
let finalDecision = null;

if (
  typeof fitScore === "number" &&
  Number.isFinite(fitScore) &&
  fitScore >= 0 &&
  fitScore <= 100
) {
  if (fitScore >= 75) {
    finalDecision = "strong_match";
  } else if (fitScore >= 60) {
    finalDecision = "possible_match";
  } else if (fitScore >= 40) {
    finalDecision = "weak_match";
  } else {
    finalDecision = "not_relevant";
  }
}

// Detect whether Qwen's decision was inconsistent
const decisionMismatch = llmDecision !== finalDecision;

// Return the original job with the parsed evaluation
return [
  {
    json: {
      ...job,

      fit_score: fitScore,

      // Deterministic decision used by downstream nodes
      decision: finalDecision,

      // Original decision produced by Qwen
      llm_decision: llmDecision,

      // Useful for our future AI evaluation harness
      decision_mismatch: decisionMismatch,

      matched_skills: score.matched_skills || [],
      missing_skills: score.missing_skills || [],
      fit_reason: score.reason || ""
    }
  }
];

// Prepare Tailored Resume Input

const items = $input.all();

return items.map(item => {
  const job = item.json;

  return {
    json: {
      ...job,

      tailoring_context: {
        job: {
          company: job.company,
          title: job.title,
          description: job.clean_description || job.description || "",
          location: job.location,
          fit_score: job.fit_score,
          matched_skills: job.matched_skills || [],
          missing_skills: job.missing_skills || []
        }
      }
    }
  };
});

