// =====================================================
// PARSE RESUME SELECTION
// Machine Learning + GenAI Resume Tailoring
// =====================================================
//
// Preserves:
// - Structured Output Parser compatibility
// - One-page / two-page resume limits
// - Strict index validation
// - Verified candidate information
// - Research experience and project evidence
// - Existing downstream output structure
//
// Improvements:
// - Compound qualification headings
// - Multiline job requirements
// - Direct and contextual skill matching
// - Job-specific skill ranking
// - Conservative MLOps evidence-gap detection
// - Detailed selection audit
// =====================================================


// =====================================================
// 1. RETRIEVE INPUT DATA
// =====================================================

const originalItems = $("Attach Candidate Profile").all();
const inputItems = $input.all();

return inputItems.map((item, index) => {

  const original = originalItems[index]?.json;

  if (!original) {
    throw new Error(
      `Original job data missing for item ${index}`
    );
  }

  const profile = original.candidate_profile;

  if (!profile) {
    throw new Error(
      `candidate_profile missing for item ${index}`
    );
  }


  // =====================================================
  // 2. PARSE LLM RESPONSE
  // =====================================================

  let selection;

  const structuredOutput = item.json.output;

  if (
    structuredOutput &&
    typeof structuredOutput === "object" &&
    !Array.isArray(structuredOutput)
  ) {
    selection = structuredOutput;
  } else {
    const raw = String(item.json.text || "")
      .replace(/^```json\s*/i, "")
      .replace(/^```\s*/i, "")
      .replace(/```$/i, "")
      .trim();

    try {
      selection = JSON.parse(raw);
    } catch (error) {
      throw new Error(
        `Could not parse resume selection JSON: ${error.message}`
      );
    }
  }

  if (
    !selection ||
    typeof selection !== "object" ||
    Array.isArray(selection)
  ) {
    throw new Error("Invalid resume selection");
  }


  // =====================================================
  // 3. PAGE LIMITS
  // =====================================================

  const targetPages = selection.target_pages;

  if (targetPages !== 1 && targetPages !== 2) {
    throw new Error(
      `Invalid target_pages: ${targetPages}`
    );
  }

  const limits = targetPages === 1
    ? {
        maxExperience: 2,
        maxExperienceBullets: 4,
        maxProjects: 2,
        maxProjectBullets: 4,
        maxSkills: 12
      }
    : {
        maxExperience: 3,
        maxExperienceBullets: 9,
        maxProjects: 2,
        maxProjectBullets: 8,
        maxSkills: 20
      };


  // =====================================================
  // 4. VALIDATE EXPERIENCE / PROJECT INDEXES
  // =====================================================

  function validateIndexes(selections, source, type) {

    if (!Array.isArray(selections)) {
      throw new Error(
        `${type}_selections must be an array`
      );
    }

    const usedIndexes = new Set();
    let totalBullets = 0;

    for (const selected of selections) {

      if (
        !selected ||
        typeof selected !== "object" ||
        Array.isArray(selected)
      ) {
        throw new Error(
          `Invalid ${type} selection object`
        );
      }

      const selectedIndex = selected[`${type}_index`];

      if (
        !Number.isInteger(selectedIndex) ||
        selectedIndex < 0 ||
        selectedIndex >= source.length
      ) {
        throw new Error(
          `Invalid ${type} index: ${selectedIndex}`
        );
      }

      if (usedIndexes.has(selectedIndex)) {
        throw new Error(
          `Duplicate ${type} index: ${selectedIndex}`
        );
      }

      usedIndexes.add(selectedIndex);

      const bullets = source[selectedIndex]?.bullets || [];

      if (!Array.isArray(bullets)) {
        throw new Error(
          `Invalid source bullets for ${type} ${selectedIndex}`
        );
      }

      if (!Array.isArray(selected.bullet_indexes)) {
        throw new Error(
          `bullet_indexes must be an array for ${type} ${selectedIndex}`
        );
      }

      const perEntryLimit =
        type === "experience"
          ? targetPages === 1
            ? 4
            : 5
          : 5;

      if (selected.bullet_indexes.length > perEntryLimit) {
        throw new Error(
          `Too many bullets in ${type} ${selectedIndex}`
        );
      }

      for (const bulletIndex of selected.bullet_indexes) {

        if (
          !Number.isInteger(bulletIndex) ||
          bulletIndex < 0 ||
          bulletIndex >= bullets.length
        ) {
          throw new Error(
            `Invalid bullet index ${bulletIndex} in ${type} ${selectedIndex}`
          );
        }
      }

      if (
        new Set(selected.bullet_indexes).size !==
        selected.bullet_indexes.length
      ) {
        throw new Error(
          `Duplicate bullet indexes in ${type} ${selectedIndex}`
        );
      }

      totalBullets += selected.bullet_indexes.length;
    }

    const maxEntries =
      type === "experience"
        ? limits.maxExperience
        : limits.maxProjects;

    const maxBullets =
      type === "experience"
        ? limits.maxExperienceBullets
        : limits.maxProjectBullets;

    if (selections.length > maxEntries) {
      throw new Error(
        `Too many ${type} entries. Maximum: ${maxEntries}`
      );
    }

    if (totalBullets > maxBullets) {
      throw new Error(
        `Too many ${type} bullets. Maximum: ${maxBullets}`
      );
    }
  }


  // =====================================================
  // 5. VALIDATE SKILLS
  // =====================================================

  function normalizeSkill(value) {
    return String(value || "")
      .toLowerCase()
      .trim()
      .replace(/\s+/g, " ");
  }

  function validateSkills(skillSelections) {

    if (!Array.isArray(skillSelections)) {
      throw new Error(
        "skill_selections must be an array"
      );
    }

    const usedIndexes = new Set();
    const usedNames = new Set();

    for (const selected of skillSelections) {

      if (
        !selected ||
        typeof selected !== "object" ||
        Array.isArray(selected)
      ) {
        throw new Error(
          "Invalid skill selection object"
        );
      }

      const { category, skill_index: skillIndex } = selected;

      const categorySkills = profile.skills?.[category];

      if (!Array.isArray(categorySkills)) {
        throw new Error(
          `Invalid skill category: ${category}`
        );
      }

      if (
        !Number.isInteger(skillIndex) ||
        skillIndex < 0 ||
        skillIndex >= categorySkills.length
      ) {
        throw new Error(
          `Invalid skill index ${skillIndex} in ${category}`
        );
      }

      const key = `${category}:${skillIndex}`;

      if (usedIndexes.has(key)) {
        throw new Error(
          `Duplicate skill index: ${key}`
        );
      }

      usedIndexes.add(key);

      const name = normalizeSkill(categorySkills[skillIndex]);

      if (usedNames.has(name)) {
        throw new Error(
          `Duplicate skill name: ${name}`
        );
      }

      usedNames.add(name);
    }

    if (skillSelections.length > limits.maxSkills) {
      throw new Error(
        `Too many selected skills. Maximum: ${limits.maxSkills}`
      );
    }
  }


  // =====================================================
  // 6. VALIDATE ORIGINAL AI SELECTION
  // =====================================================

  validateIndexes(
    selection.experience_selections,
    profile.experience || [],
    "experience"
  );

  validateIndexes(
    selection.project_selections,
    profile.projects || [],
    "project"
  );

  validateSkills(selection.skill_selections);

  if (selection.include_education !== true) {
    throw new Error("include_education must be true");
  }

  if (selection.include_languages !== true) {
    throw new Error("include_languages must be true");
  }

  if (!Array.isArray(selection.missing_requirements)) {
    throw new Error(
      "missing_requirements must be an array"
    );
  }


  // =====================================================
  // 7. CREATE EDITABLE SELECTION
  // =====================================================

  const refined = {
    ...selection,

    experience_selections:
      selection.experience_selections.map(sel => ({
        experience_index: sel.experience_index,
        bullet_indexes: [...sel.bullet_indexes]
      })),

    project_selections:
      selection.project_selections.map(sel => ({
        project_index: sel.project_index,
        bullet_indexes: [...sel.bullet_indexes]
      })),

    skill_selections:
      selection.skill_selections.map(sel => ({
        category: sel.category,
        skill_index: sel.skill_index
      })),

    missing_requirements:
      [...selection.missing_requirements]
  };


  // =====================================================
  // 8. JOB DESCRIPTION
  // =====================================================

  const jobDescription = String(
    original.tailoring_context?.job?.description ||
    original.clean_description ||
    ""
  );


  // =====================================================
  // 9. EXTRACT REQUIRED / PREFERRED REQUIREMENTS
  // =====================================================

  function extractSkillSection(text, heading) {

    const lines = String(text || "").split(/\r?\n/);

    const extracted = [];

    let inside = false;
    let current = "";

    const flush = () => {
      if (current.trim()) {
        extracted.push(current.trim());
      }

      current = "";
    };

    for (const line of lines) {

      const trimmed = line.trim();

      if (!trimmed) continue;

      const title = trimmed
        .replace(/[:：]\s*$/, "")
        .trim();

      const isRequired =
        /^(required(?:\s+technical)?\s+(?:skills?|qualifications?)(?:\s*(?:&|and|\/)\s*(?:skills?|qualifications?))?|minimum qualifications?|requirements?|must[- ]have)$/i
          .test(title);

      const isPreferred =
        /^(preferred(?:\s+(?:skills?|qualifications?))?|nice[- ]to[- ]have|bonus skills|desirable skills)$/i
          .test(title);

      const knownBoundary =
        /^(role|location|role overview|about the (?:role|job)|key responsibilities|responsibilities|additional information|more about the opportunity|equal opportunity employer|tech stack|technology stack)$/i
          .test(title);

      const otherHeading =
        !/^[-*•]\s*/.test(trimmed) &&
        /^[A-Z][A-Z0-9 &/()-]+[:：]?$/.test(trimmed) &&
        trimmed.length <= 65;

      if (isRequired || isPreferred) {

        flush();

        inside =
          heading === (isRequired ? "required" : "preferred");

        continue;
      }

      if (inside && (knownBoundary || otherHeading)) {
        flush();
        inside = false;
        continue;
      }

      if (!inside) continue;

      if (/^[-*•]\s+/.test(trimmed)) {

        flush();

        current = trimmed.replace(/^[-*•]\s+/, "");

      } else if (current) {

        // Continue an existing multiline requirement.
        current += " " + trimmed;
      }
    }

    flush();

    return extracted;
  }

  const requiredSkills =
    extractSkillSection(jobDescription, "required");

  const preferredSkills =
    extractSkillSection(jobDescription, "preferred");


  // =====================================================
  // 10. BUILD VERIFIED SKILL INDEX
  // =====================================================

  const verifiedSkills = [];

  for (
    const [category, skills]
    of Object.entries(profile.skills || {})
  ) {

    if (!Array.isArray(skills)) continue;

    skills.forEach((skill, skillIndex) => {

      verifiedSkills.push({
        category,
        skill_index: skillIndex,
        name: String(skill),
        normalized: normalizeSkill(skill)
      });

    });
  }

  function findVerifiedSkill(requirement) {

    const normalized = normalizeSkill(requirement);

    return verifiedSkills.find(
      skill => skill.normalized === normalized
    ) || null;
  }

  const requiredMatches =
    requiredSkills.map(findVerifiedSkill).filter(Boolean);

  const preferredMatches =
    preferredSkills.map(findVerifiedSkill).filter(Boolean);


  // =====================================================
  // 11. SKILL ALIASES
  // =====================================================

  const skillAliases = {

    "python": ["python"],

    "javascript": [
      "javascript",
      "java script"
    ],

    "sql": ["sql"],

    "pytorch": ["pytorch"],

    "tensorflow": ["tensorflow"],

    "scikit-learn": [
      "scikit-learn",
      "scikit learn"
    ],

    "rag": [
      "rag",
      "retrieval augmented generation",
      "retrieval-augmented generation"
    ],

    "qdrant": ["qdrant"],

    "google adk": [
      "google adk",
      "agent development kit"
    ],

    "gemini api": [
      "gemini api",
      "gemini"
    ],

    "function calling": [
      "function calling",
      "tool calling",
      "function-calling"
    ],

    "human-in-the-loop systems": [
      "human in the loop",
      "human-in-the-loop",
      "human approval",
      "human review"
    ],

    "docker": [
      "docker",
      "docker compose",
      "containerization",
      "containerisation"
    ],

    "n8n": ["n8n"],

    "ollama": ["ollama"],

    "fastapi": ["fastapi"],

    "vertex ai": [
      "vertex ai",
      "vertexai"
    ],

    "cloud run": ["cloud run"],

    "pub/sub": [
      "pub/sub",
      "google pub sub",
      "google pubsub"
    ],

    "git": ["git"],

    "gitlab ci": [
      "gitlab ci",
      "gitlab ci/cd"
    ]
  };


  // =====================================================
  // 12. CONTEXTUAL MATCHING
  // =====================================================

  // Contextual matching indicates relevance.
  // It does not establish additional experience.

  const contextualAliases = {

    "qdrant": [
      "vector database",
      "vector databases",
      "vector db",
      "vector store",
      "vector stores"
    ],

    "n8n": [
      "workflow automation",
      "automated workflows",
      "workflow orchestration"
    ],

    "google adk": [
      "ai agents",
      "ai agent",
      "agentic ai",
      "agent development",
      "ai assistants",
      "ai assistant"
    ],

    "ollama": [
      "llm applications",
      "llm application",
      "large language models",
      "large language model",
      "local llm",
      "llms"
    ],

    "gemini api": [
      "generative ai",
      "genai",
      "llm application development",
      "llm applications",
      "llm application"
    ],

    "function calling": [
      "ai agents",
      "ai agent",
      "tool use",
      "agentic workflows"
    ],

    "human-in-the-loop systems": [
      "human oversight",
      "human approval workflows",
      "human review workflows"
    ],

    "fastapi": [
      "api development",
      "api integrations",
      "rest api",
      "rest apis"
    ],

    "scikit-learn": [
      "machine learning frameworks",
      "statistical modeling",
      "statistical modelling"
    ],

    "vertex ai": [
      "google cloud",
      "gcp"
    ],

    "gitlab ci": [
      "continuous integration",
      "ci/cd",
      "mlops"
    ]
  };


  // =====================================================
  // 13. SAFE PHRASE MATCHING
  // =====================================================

  function escapeRegex(value) {

    return String(value).replace(
      /[.*+?^${}()|[\]\\]/g,
      "\\$&"
    );
  }

  function containsPhrase(text, phrase) {

    const normalizedText = String(text || "")
      .toLowerCase();

    const normalizedPhrase = String(phrase || "")
      .toLowerCase()
      .trim();

    if (!normalizedPhrase) return false;

    const pattern = new RegExp(
      `(^|[^a-z0-9])${escapeRegex(normalizedPhrase)}(?=$|[^a-z0-9])`,
      "i"
    );

    return pattern.test(normalizedText);
  }


  // =====================================================
  // 14. CLASSIFY JOB HEADINGS
  // =====================================================

  function classifyHeading(heading) {

    const value = normalizeSkill(
      heading.replace(/[:：]$/, "")
    );

    if (
      /^(preferred skills|nice to have|nice-to-have|preferred qualifications|bonus skills|desirable skills)$/
        .test(value)
    ) {
      return "preferred";
    }

    if (
      /^(required(?: technical)? (?:skills?|qualifications?)(?:\s*(?:&|and|\/)\s*(?:skills?|qualifications?))?|must have|must-have|minimum qualifications|required qualifications|requirements|qualifications|about you|your profile)$/
        .test(value)
    ) {
      return "qualification";
    }

    if (
      /^(tech stack|technology stack|technologies|tools and technologies|technical stack)$/
        .test(value)
    ) {
      return "tech_stack";
    }

    if (
      /^(key responsibilities|responsibilities|your responsibilities|tasks|about your tasks|what you will do|job description)$/
        .test(value)
    ) {
      return "responsibility";
    }

    return "general";
  }


  // =====================================================
  // 15. PARSE JOB SECTIONS
  // =====================================================

  function parseJobSections(text) {

    const lines = String(text || "").split(/\r?\n/);

    const sections = [];

    let currentType = "general";

    for (const line of lines) {

      const trimmed = line.trim();

      if (!trimmed) continue;

      const possibleHeading = trimmed
        .replace(/[:：]\s*$/, "")
        .trim();

      const headingType = classifyHeading(
        possibleHeading
      );

      if (
        headingType !== "general" &&
        (
          /[:：]\s*$/.test(trimmed) ||
          trimmed.length <= 35
        )
      ) {

        currentType = headingType;
        continue;
      }

      // An unrecognized uppercase heading ends
      // the previous section.

      if (
        trimmed.length <= 55 &&
        /^[A-Z][A-Z0-9 &/()-]+[:：]?$/.test(trimmed) &&
        trimmed.replace(/[:：]$/, "").length >= 4
      ) {

        currentType = "general";
        continue;
      }

      sections.push({
        type: currentType,
        text: trimmed.replace(/^[-*•]\s*/, "")
      });
    }

    return sections;
  }

  const jobSections = parseJobSections(jobDescription);


  // =====================================================
  // 16. SECTION PRIORITY
  // =====================================================

  const sectionWeights = {
    qualification: 5,
    preferred: 3,
    tech_stack: 3,
    responsibility: 3,
    general: 1
  };


  // =====================================================
  // 17. SCORE VERIFIED SKILLS
  // =====================================================

  function findSkillEvidence(skill) {

    const normalizedName = skill.normalized;

    const exactAliases = [
      skill.name,
      ...(skillAliases[normalizedName] || [])
    ];

    const contextualTerms =
      contextualAliases[normalizedName] || [];

    let bestScore = 0;

    const evidence = [];

    for (const section of jobSections) {

      const weight = sectionWeights[section.type] || 1;

      const directMatch = exactAliases.find(
        alias => containsPhrase(section.text, alias)
      );

      const contextualMatch = contextualTerms.find(
        alias => containsPhrase(section.text, alias)
      );

      if (directMatch) {

        const score = weight * 10 + 10;

        bestScore = Math.max(bestScore, score);

        evidence.push({
          section: section.type,
          type: "direct",
          matched_phrase: directMatch,
          score
        });

      } else if (contextualMatch) {

        const score = weight * 10;

        bestScore = Math.max(bestScore, score);

        evidence.push({
          section: section.type,
          type: "contextual",
          matched_phrase: contextualMatch,
          score
        });
      }
    }

    return {
      ...skill,
      relevance_score: bestScore,
      evidence
    };
  }

  const scoredVerifiedSkills =
    verifiedSkills.map(findSkillEvidence);


  // =====================================================
  // 18. RANK RELEVANT SKILLS
  // =====================================================

  const skillKey = skill =>
    `${skill.category}:${skill.skill_index}`;

  const requiredKeys = new Set(
    requiredMatches.map(skillKey)
  );

  const preferredKeys = new Set(
    preferredMatches.map(skillKey)
  );

  const originalAIKeys = new Set(
    refined.skill_selections.map(skillKey)
  );

  const rankedSkills = scoredVerifiedSkills
    .map(skill => {

      let priority = skill.relevance_score;

      if (requiredKeys.has(skillKey(skill))) {
        priority += 1000;
      }

      if (preferredKeys.has(skillKey(skill))) {
        priority += 500;
      }

      if (originalAIKeys.has(skillKey(skill))) {
        priority += 5;
      }

      return {
        ...skill,
        priority
      };
    })
    .filter(skill =>
      skill.relevance_score > 0 ||
      originalAIKeys.has(skillKey(skill))
    )
    .sort((a, b) => {

      if (b.priority !== a.priority) {
        return b.priority - a.priority;
      }

      const aDirect = a.evidence.some(
        item => item.type === "direct"
      );

      const bDirect = b.evidence.some(
        item => item.type === "direct"
      );

      if (aDirect !== bDirect) {
        return bDirect ? 1 : -1;
      }

      return verifiedSkills.findIndex(
        skill => skillKey(skill) === skillKey(a)
      ) -
      verifiedSkills.findIndex(
        skill => skillKey(skill) === skillKey(b)
      );
    });


  // =====================================================
  // 19. SELECT SKILLS
  // =====================================================

  const orderedSkills = [];

  const seenSkills = new Set();
  const seenNames = new Set();

  function addSkill(skill) {

    const key = skillKey(skill);

    const categorySkills =
      profile.skills?.[skill.category];

    if (!Array.isArray(categorySkills)) return;

    const name = normalizeSkill(
      categorySkills[skill.skill_index]
    );

    if (
      seenSkills.has(key) ||
      seenNames.has(name)
    ) {
      return;
    }

    seenSkills.add(key);
    seenNames.add(name);

    orderedSkills.push({
      category: skill.category,
      skill_index: skill.skill_index
    });
  }

  // Include skills supported by the job description first.
  rankedSkills
    .filter(skill => skill.relevance_score > 0)
    .forEach(addSkill);

  const matchedSkillCount = orderedSkills.length;

  // Allow fewer unrelated AI-selected skills when
  // sufficient job-specific skills were found.

  const fallbackLimit =
    matchedSkillCount >= 5 ? 1 : 4;

  const fallbackCategoryPriority = {
    machine_learning: 0,
    programming: 1,
    speech_and_vision: 2,
    cloud_and_infrastructure: 3,
    llm_and_agents: 4
  };

  const fallbackSkills = rankedSkills
    .filter(skill => skill.relevance_score === 0)
    .sort((a, b) =>
      (fallbackCategoryPriority[a.category] ?? 5) -
      (fallbackCategoryPriority[b.category] ?? 5)
    );

  fallbackSkills
    .slice(0, fallbackLimit)
    .forEach(addSkill);

  refined.skill_selections =
    orderedSkills.slice(0, limits.maxSkills);


  // =====================================================
  // 20. PRESERVE RESEARCH DEPTH
  // =====================================================

  if (targetPages === 2) {

    const experienceSelections =
      refined.experience_selections;

    const countExperienceBullets = () =>
      experienceSelections.reduce(
        (total, sel) =>
          total + sel.bullet_indexes.length,
        0
      );

    function addExperienceBullet(
      experienceIndex,
      bulletIndex
    ) {

      const selected = experienceSelections.find(
        sel => sel.experience_index === experienceIndex
      );

      // Do not introduce unselected experience.
      if (!selected) return false;

      const source =
        profile.experience?.[experienceIndex];

      if (
        !source ||
        !Array.isArray(source.bullets) ||
        !source.bullets[bulletIndex]
      ) {
        return false;
      }

      if (
        selected.bullet_indexes.includes(bulletIndex)
      ) {
        return false;
      }

      if (
        selected.bullet_indexes.length >= 5 ||
        countExperienceBullets() >=
          limits.maxExperienceBullets
      ) {
        return false;
      }

      selected.bullet_indexes.push(bulletIndex);

      return true;
    }

    // Preserve the measurable Speech Emotion
    // Recognition result whenever selected.

    addExperienceBullet(1, 3);

    const selectedResearchIndexes = new Set(
      experienceSelections.map(
        sel => sel.experience_index
      )
    );

    const hasMainResearch =
      selectedResearchIndexes.has(0) &&
      selectedResearchIndexes.has(1);

    if (
      hasMainResearch &&
      countExperienceBullets() < 7
    ) {

      const researchPriority = [
        [0, 0],
        [0, 1],
        [1, 0],
        [1, 1],
        [0, 3],
        [0, 2],
        [1, 2],
        [0, 4]
      ];

      for (
        const [experienceIndex, bulletIndex]
        of researchPriority
      ) {

        if (countExperienceBullets() >= 7) {
          break;
        }

        addExperienceBullet(
          experienceIndex,
          bulletIndex
        );
      }
    }

    // Restore the original verified bullet order.

    for (const sel of experienceSelections) {
      sel.bullet_indexes.sort((a, b) => a - b);
    }
  }


  // =====================================================
  // 21. REMOVE COURSE/TUTORIAL DESCRIPTION BULLETS
  // =====================================================

  const projectSelections = refined.project_selections;

  for (const sel of projectSelections) {

    const project =
      profile.projects?.[sel.project_index];

    if (!project) continue;

    sel.bullet_indexes = sel.bullet_indexes.filter(
      bulletIndex => {

        const bullet = String(
          project.bullets?.[bulletIndex] || ""
        );

        const courseDescription =
          /created through .*course|official codelabs|course and .*codelabs/i
            .test(bullet);

        return !courseDescription;
      }
    );
  }

  refined.project_selections =
    projectSelections.filter(
      sel => sel.bullet_indexes.length > 0
    );


  // =====================================================
  // 22. REVALIDATE REFINED SELECTIONS
  // =====================================================

  validateIndexes(
    refined.experience_selections,
    profile.experience || [],
    "experience"
  );

  validateIndexes(
    refined.project_selections,
    profile.projects || [],
    "project"
  );

  validateSkills(refined.skill_selections);


  // =====================================================
  // 23. BUILD SELECTED EXPERIENCE
  // =====================================================

  const selectedExperience =
    refined.experience_selections.map(sel => {

      const exp =
        profile.experience[sel.experience_index];

      const bullets = sel.bullet_indexes.map(
        bulletIndex => exp.bullets[bulletIndex]
      );

      return {
        role: exp.role,
        organization: exp.organization,
        dates: exp.dates,
        location: exp.location,
        bullets,
        technologies: exp.technologies || []
      };
    });


  // =====================================================
  // 24. BUILD SELECTED PROJECTS
  // =====================================================

  const selectedProjects =
    refined.project_selections.map(sel => {

      const project =
        profile.projects[sel.project_index];

      const bullets = sel.bullet_indexes.map(
        bulletIndex => project.bullets[bulletIndex]
      );

      return {
        name: project.name,
        subtitle: project.subtitle || "",
        status: project.status || "",
        bullets,
        technologies: project.technologies || []
      };
    });


  // =====================================================
  // 25. BUILD SELECTED SKILLS
  // =====================================================

  const selectedSkills =
    refined.skill_selections.map(sel => ({
      category: sel.category,
      skill:
        profile.skills[sel.category][sel.skill_index]
    }));


  // =====================================================
  // 26. CHECK MISSING EXPERIENCE EVIDENCE
  // =====================================================

  const cleanedMissingRequirements =
    refined.missing_requirements
      .filter(requirement =>
        typeof requirement === "string" &&
        requirement.trim()
      )
      .map(requirement => requirement.trim());

  const demonstratedWork = [
    ...(profile.experience || []).flatMap(
      exp => exp.bullets || []
    ),
    ...(profile.projects || []).flatMap(
      project => project.bullets || []
    )
  ].join(" ").toLowerCase();

  const potentialGaps = [];

  // This is a documentation gap, not proof that
  // the candidate lacks the underlying skill.

  if (
    /\bmlops\b|model monitoring/i.test(jobDescription) &&
    !/model monitoring|model drift|ml model monitoring/i
      .test(demonstratedWork)
  ) {
    potentialGaps.push(
      "Production ML model monitoring is not demonstrated in the verified project/research bullets"
    );
  }

  if (
    /deploy (?:models|machine learning models) (?:into )?production|production environments/i
      .test(jobDescription) &&
    !/(?:production[- ]deployed|deployed (?:an? )?(?:ml|machine learning|deep learning|predictive) model|model serving in production)/i
      .test(demonstratedWork)
  ) {
    potentialGaps.push(
      "Production deployment of a trained ML model is not demonstrated in the verified project/research bullets"
    );
  }

  const missingSet = new Set(
    cleanedMissingRequirements.map(
      value => value.toLowerCase()
    )
  );

  for (const gap of potentialGaps) {

    if (!missingSet.has(gap.toLowerCase())) {

      cleanedMissingRequirements.push(gap);
      missingSet.add(gap.toLowerCase());
    }
  }


  // =====================================================
  // 27. BUILD TAILORED RESUME
  // =====================================================

  const tailoredResume = {

    name: profile.name,

    headline: profile.headline,

    target_pages: targetPages,

    selected_experience: selectedExperience,

    selected_projects: selectedProjects,

    selected_skills: selectedSkills,

    education: profile.education || [],

    languages: profile.languages || [],

    missing_requirements:
      cleanedMissingRequirements
  };


  // =====================================================
  // 28. BUILD SELECTION AUDIT
  // =====================================================

  const selectedSkillKeys = new Set(
    refined.skill_selections.map(skillKey)
  );

  const skillMatchAudit = rankedSkills
    .filter(skill =>
      selectedSkillKeys.has(skillKey(skill))
    )
    .map(skill => {

      const strongestEvidence =
        [...skill.evidence].sort(
          (a, b) => b.score - a.score
        )[0] || null;

      return {

        skill: skill.name,

        category: skill.category,

        relevance_score: skill.relevance_score,

        selected_by_ai:
          originalAIKeys.has(skillKey(skill)),

        evidence_type:
          strongestEvidence?.type ||
          "ai_selection_only",

        matched_phrase:
          strongestEvidence?.matched_phrase || null,

        job_section:
          strongestEvidence?.section || null
      };
    });


  // =====================================================
  // 29. RETURN ORIGINAL DATA + REFINED SELECTION
  // =====================================================

  return {

    json: {

      ...original,

      resume_selection: refined,

      tailored_resume: tailoredResume,

      resume_selection_audit: {

        required_skills_found: requiredSkills,

        preferred_skills_found: preferredSkills,

        verified_required_skills:
          scoredVerifiedSkills
            .filter(skill =>
              skill.evidence.some(
                evidence =>
                  evidence.section === "qualification" &&
                  evidence.type === "direct"
              )
            )
            .map(skill => skill.name),

        verified_preferred_skills:
          scoredVerifiedSkills
            .filter(skill =>
              skill.evidence.some(
                evidence =>
                  evidence.section === "preferred" &&
                  evidence.type === "direct"
              )
            )
            .map(skill => skill.name),

        potential_experience_gaps: potentialGaps,

        required_section_detected:
          requiredSkills.length > 0,

        job_sections_analyzed: jobSections.length,

        verified_job_skill_matches:
          scoredVerifiedSkills
            .filter(
              skill => skill.relevance_score > 0
            )
            .map(skill => skill.name),

        skill_match_details: skillMatchAudit,

        selected_experience_bullets:
          selectedExperience.reduce(
            (total, exp) =>
              total + exp.bullets.length,
            0
          ),

        selected_project_bullets:
          selectedProjects.reduce(
            (total, project) =>
              total + project.bullets.length,
            0
          ),

        selected_skill_count:
          selectedSkills.length
      }
    }
  };

});

// =====================================================
// BUILD TAILORED RESUME
// =====================================================
// Builds the final resume using verified candidate data.
// Supports 1-page and 2-page resumes.
// Preserves all job metadata and original workflow data.
//
// Fix:
// - Preserves null fit_score for unevaluated jobs.
// - Keeps valid numeric fit scores unchanged.
// - Does not assign an artificial score of zero.
//
// Does not generate or invent candidate information.
// =====================================================

const inputItems = $input.all();

return inputItems.map((item, index) => {

  // ---------------------------------------------------
  // 1. VALIDATE INPUT
  // ---------------------------------------------------

  const data = item.json;

  const profile = data.candidate_profile;
  const resume = data.tailored_resume;

  if (!profile || typeof profile !== "object") {
    throw new Error(
      `Missing candidate_profile for item ${index}`
    );
  }

  if (!resume || typeof resume !== "object") {
    throw new Error(
      `Missing tailored_resume for item ${index}`
    );
  }

  if (!profile.name) {
    throw new Error(
      `Candidate name missing for item ${index}`
    );
  }

  // ---------------------------------------------------
  // 2. VALIDATE TARGET PAGES
  // ---------------------------------------------------

  const targetPages = resume.target_pages;

  if (targetPages !== 1 && targetPages !== 2) {
    throw new Error(
      `Invalid target_pages for item ${index}: ${targetPages}`
    );
  }

  // ---------------------------------------------------
  // 3. PREPARE SELECTED CONTENT
  // ---------------------------------------------------

  const selectedExperience =
    Array.isArray(resume.selected_experience)
      ? resume.selected_experience
      : [];

  const selectedProjects =
    Array.isArray(resume.selected_projects)
      ? resume.selected_projects
      : [];

  const selectedSkills =
    Array.isArray(resume.selected_skills)
      ? resume.selected_skills
      : [];

  const education =
    Array.isArray(resume.education)
      ? resume.education
      : [];

  const languages =
    Array.isArray(resume.languages)
      ? resume.languages
      : [];

  // ---------------------------------------------------
  // 4. ORGANIZE SKILLS BY CATEGORY
  // ---------------------------------------------------

  const selectedSkillsByCategory = {};

  for (const entry of selectedSkills) {

    if (
      !entry ||
      typeof entry.category !== "string" ||
      typeof entry.skill !== "string"
    ) {
      throw new Error(
        `Invalid skill selection for item ${index}`
      );
    }

    const category = entry.category;
    const skill = entry.skill;

    if (!selectedSkillsByCategory[category]) {
      selectedSkillsByCategory[category] = [];
    }

    if (!selectedSkillsByCategory[category].includes(skill)) {
      selectedSkillsByCategory[category].push(skill);
    }
  }

  // ---------------------------------------------------
  // 5. PRESERVE MISSING REQUIREMENTS
  // ---------------------------------------------------

  const missingRequirements =
    Array.isArray(resume.missing_requirements)
      ? resume.missing_requirements
      : [];

  // ---------------------------------------------------
  // 6. PRESERVE JOB FIT SCORE
  // ---------------------------------------------------

  // An unevaluated job must have fit_score = null.
  //
  // A valid score of 0 is different from null:
  //
  // null = not evaluated
  // 0    = evaluated and received a score of zero
  //
  // Preserve valid numeric scores between 0 and 100.

  let fitScore = null;

  if (
    typeof data.fit_score === "number" &&
    Number.isFinite(data.fit_score) &&
    data.fit_score >= 0 &&
    data.fit_score <= 100
  ) {

    fitScore = data.fit_score;

  }

  // ---------------------------------------------------
  // 7. BUILD FINAL RESUME
  // ---------------------------------------------------

  const finalResume = {

    target_pages: targetPages,

    header: {

      name: profile.name,

      headline: profile.headline || "",

      location: "Aachen, Germany",

      email: "tarunphanindra334@gmail.com",

      // Confirmed LinkedIn URL
      linkedin:
        "https://www.linkedin.com/in/tarun-phanindra-maddu",

      // Confirmed GitHub URL
      github:
        "https://github.com/TarunPhanindra"

    },

    profile: profile.profile || "",

    skills: selectedSkillsByCategory,

    experience: selectedExperience,

    projects: selectedProjects,

    education: education,

    languages: languages,

    metadata: {

      target_company:
        data.company ??
        data.tailoring_context?.job?.company ??
        "",

      target_title:
        data.title ??
        data.tailoring_context?.job?.title ??
        "",

      // Correctly preserve null for unevaluated jobs.
      fit_score: fitScore,

      decision:
        data.decision ?? "",

      evaluation_valid:
        data.evaluation_valid ?? false,

      llm_decision:
        data.llm_decision ?? "",

      decision_mismatch:
        data.decision_mismatch ?? false,

      missing_requirements: missingRequirements

    }
  };

  // ---------------------------------------------------
  // 8. RETURN RESULT
  // ---------------------------------------------------

  return {
    json: {
      ...data,

      final_resume: finalResume
    }
  };

});

// =====================================================
// GENERATE RESUME HTML
// =====================================================
// Features:
// - Adaptive 1-page and 2-page resume layouts
// - ATS-friendly HTML
// - A4 PDF compatibility with Gotenberg
// - Clickable email, LinkedIn and GitHub
// - Safe HTML escaping
// - Experience and project page-break protection
// - Improved project spacing for two-page resumes
// - Preserves all upstream workflow data
//
// This node formats existing resume content.
// It does not generate or invent candidate information.
// =====================================================


// =====================================================
// 1. HTML ESCAPING
// =====================================================

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}


// =====================================================
// 2. SAFE URL VALIDATION
// =====================================================

function safeHttpsUrl(value) {

  if (typeof value !== "string") {
    return "";
  }

  const url = value.trim();

  // Only allow HTTPS URLs.
  if (!/^https:\/\/[a-z0-9.-]+(?:[/:?#]|$)/i.test(url)) {
    return "";
  }

  // Reject spaces and unsafe characters.
  if (/[\s<>"'\\]/.test(url)) {
    return "";
  }

  return url;
}


// =====================================================
// 3. GENERATE CLICKABLE CONTACT INFORMATION
// =====================================================

function buildContactHtml(header) {

  const contactParts = [];


  // ---------------------------------------------------
  // LOCATION
  // ---------------------------------------------------

  if (header.location) {

    contactParts.push(
      escapeHtml(header.location)
    );

  }


  // ---------------------------------------------------
  // EMAIL
  // ---------------------------------------------------

  if (header.email) {

    const email = String(header.email).trim();

    if (
      /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(email)
    ) {

      contactParts.push(
        `<a href="mailto:${escapeHtml(email)}">${escapeHtml(email)}</a>`
      );

    } else {

      contactParts.push(
        escapeHtml(email)
      );

    }

  }


  // ---------------------------------------------------
  // LINKEDIN
  // ---------------------------------------------------

  if (header.linkedin) {

    const linkedinUrl = safeHttpsUrl(
      header.linkedin
    );

    if (
      linkedinUrl &&
      /^https:\/\/(www\.)?linkedin\.com(?:[/:?#]|$)/i.test(linkedinUrl)
    ) {

      contactParts.push(
        `<a href="${escapeHtml(linkedinUrl)}">LinkedIn</a>`
      );

    } else {

      contactParts.push(
        escapeHtml(header.linkedin)
      );

    }

  }


  // ---------------------------------------------------
  // GITHUB
  // ---------------------------------------------------

  if (header.github) {

    const githubUrl = safeHttpsUrl(
      header.github
    );

    if (
      githubUrl &&
      /^https:\/\/github\.com(?:[/:?#]|$)/i.test(githubUrl)
    ) {

      contactParts.push(
        `<a href="${escapeHtml(githubUrl)}">GitHub</a>`
      );

    } else {

      contactParts.push(
        escapeHtml(header.github)
      );

    }

  }


  // ---------------------------------------------------
  // COMBINE CONTACT DETAILS
  // ---------------------------------------------------

  return contactParts.join(
    ' <span class="contact-separator">|</span> '
  );

}


// =====================================================
// 4. PROCESS INPUT ITEMS
// =====================================================

const inputItems = $input.all();

return inputItems.map((item, index) => {

  const data = item.json;

  const resume = data.final_resume;


  // ---------------------------------------------------
  // 5. VALIDATE RESUME DATA
  // ---------------------------------------------------

  if (!resume || typeof resume !== "object") {

    throw new Error(
      `final_resume missing for item ${index}`
    );

  }

  if (!resume.header?.name) {

    throw new Error(
      `Candidate name missing for item ${index}`
    );

  }

  const targetPages = resume.target_pages;

  if (targetPages !== 1 && targetPages !== 2) {

    throw new Error(
      `Invalid target_pages: ${targetPages}. Expected 1 or 2.`
    );

  }


  // ---------------------------------------------------
  // 6. PREPARE RESUME SECTIONS
  // ---------------------------------------------------

  const experience = Array.isArray(resume.experience)
    ? resume.experience
    : [];

  const projects = Array.isArray(resume.projects)
    ? resume.projects
    : [];

  const education = Array.isArray(resume.education)
    ? resume.education
    : [];

  const languages = Array.isArray(resume.languages)
    ? resume.languages
