// =====================================================
// RENAME RESUME PDF
// =====================================================
// Generates a descriptive PDF filename.
// Preserves original job and resume metadata.
// Preserves null fit_score for unevaluated jobs.
// =====================================================

// Get resume metadata
const original = $("Build Tailored Resume").item.json;
const resume = original.final_resume || {};
const metadata = resume.metadata || {};

// Get candidate and job details
const candidateName = resume.header?.name || "Candidate";
const company = metadata.target_company || "Company";
const role = metadata.target_title || "Role";

// Make filename components safe
function safeFileName(value) {
  return String(value ?? "")
    .replace(/[^a-zA-Z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .replace(/_+/g, "_");
}

// Generate filename
const fileName = [
  safeFileName(candidateName),
  safeFileName(company),
  safeFileName(role).slice(0, 60)
].join("_") + ".pdf";

// Get the PDF from the current input item
const inputItem = $input.item;

if (!inputItem.binary?.data) {
  throw new Error("PDF binary data not found");
}

// Create binary metadata with the correct filename
const renamedBinary = {
  ...inputItem.binary,

  data: {
    ...inputItem.binary.data,
    fileName,
    fileExtension: "pdf",
    mimeType: "application/pdf"
  }
};

// Return the renamed PDF
return {
  json: {
    ...original,
    company,
    role,
    file_name: fileName,

    // Preserve null instead of converting it to zero.
    fit_score: metadata.fit_score ?? null
  },

  binary: renamedBinary
};

// ======================================================
// VALIDATE AI EVALUATION — VERSION 3.3
// ======================================================
//
// Improvements:
// 1. Context-aware university enrollment checks
// 2. Mandatory advanced German requirement checks
// 3. Verified skill normalization
// 4. Corrected formal leadership requirement detection
// 5. Preservation of existing scoring and validation
// 6. No changes to candidate CV or PDF generation
//
// Important:
// This validator performs conservative rule checks.
// It is not a complete semantic verification engine.
//
// ======================================================

const job = $input.item.json;

const errors = [];
const warnings = [];

// ======================================================
// 1. HELPER FUNCTIONS
// ======================================================

function normalize(value) {
  return String(value ?? "")
    .toLowerCase()
    .replace(/[_-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function addError(message) {
  if (!errors.includes(message)) {
    errors.push(message);
  }
}

function addWarning(message) {
  if (!warnings.includes(message)) {
    warnings.push(message);
  }
}

// ======================================================
// 2. VALIDATE JOB INFORMATION
// ======================================================

if (!job.external_id || !job.company || !job.title) {
  addError("Missing job identification information");
}

const description = String(
  job.clean_description || job.description || ""
);

if (!description.trim()) {
  addError("Missing job description");
}

const title = String(job.title || "");

// Preserve the complete job description.
const jobText = normalize(`${title} ${description}`);

// Extract the text before an explicit NOT REQUIRED section.
//
// This prevents some explicitly excluded requirements
// from being treated as mandatory.
//
// Note:
// Section-aware negation handling is a future improvement.
// This approach can miss requirements following that section.

const requirementText = normalize(
  `${title} ${description.split(/\bNOT REQUIRED\s*:/i)[0]}`
);

// ======================================================
// 3. VALIDATE FIT SCORE
// ======================================================

const score = job.fit_score;

const validScore =
  typeof score === "number" &&
  Number.isFinite(score) &&
  score >= 0 &&
  score <= 100;

if (!validScore) {
  addError("fit_score must be a number between 0 and 100");
}

// ======================================================
// 4. VALIDATE DECISION
// ======================================================

const validDecisions = [
  "strong_match",
  "possible_match",
  "weak_match",
  "not_relevant"
];

if (!validDecisions.includes(job.decision)) {
  addError("Invalid decision category");
}

let expectedDecision = null;

if (validScore) {
  expectedDecision =
    score >= 75 ? "strong_match" :
    score >= 60 ? "possible_match" :
    score >= 40 ? "weak_match" :
    "not_relevant";

  if (job.decision !== expectedDecision) {
    addError(
      `Decision mismatch: expected ${expectedDecision}, received ${job.decision}`
    );
  }
}

if (
  job.decision_mismatch === true ||
  (
    expectedDecision !== null &&
    typeof job.llm_decision === "string" &&
    job.llm_decision !== expectedDecision
  )
) {
  addError("Original LLM decision mismatch");
}

