  "FastAPI": [
    "fastapi"
  ],

  "CUDA/HPC": [
    "cuda",
    "cuda/hpc",
    "gpu/hpc"
  ],

  "Git": [
    "git"
  ],

  "GitLab CI": [
    "gitlab ci"
  ]

};

// ======================================================
// 6. BUILD VERIFIED SKILL LOOKUP
// ======================================================

const skillLookup = new Map();

for (const [canonical, aliases] of Object.entries(skillAliases)) {

  skillLookup.set(normalize(canonical), canonical);

  for (const alias of aliases) {
    skillLookup.set(normalize(alias), canonical);
  }

}

// ======================================================
// 7. VALIDATE MATCHED SKILLS
// ======================================================

const normalizedMatchedSkills = [];
const unverifiedMatchedSkills = [];

const validMatchedSkills =
  Array.isArray(job.matched_skills) &&
  job.matched_skills.every(
    skill =>
      typeof skill === "string" &&
      skill.trim().length > 0
  );

if (!validMatchedSkills) {

  addError(
    "matched_skills must be an array of nonempty strings"
  );

} else {

  for (const skill of job.matched_skills) {

    const canonical = skillLookup.get(normalize(skill));

    if (!canonical) {

      unverifiedMatchedSkills.push(skill);

      addError(`Unverified matched skill: ${skill}`);

      continue;
    }

    if (!normalizedMatchedSkills.includes(canonical)) {
      normalizedMatchedSkills.push(canonical);
    }

  }

}

// ======================================================
// 8. VALIDATE MISSING SKILLS
// ======================================================

const validMissingSkills =
  Array.isArray(job.missing_skills) &&
  job.missing_skills.every(
    skill =>
      typeof skill === "string" &&
      skill.trim().length > 0
  );

if (!validMissingSkills) {
  addError(
    "missing_skills must be an array of nonempty strings"
  );
}

// ======================================================
// 8A. VERIFIED MISSING-SKILL CONTRADICTIONS — V3.4
// ======================================================
//
// Detect verified candidate skills incorrectly reported
// as missing.
//
// Keep the original missing_skills array unchanged.
// Flag contradictions for correction and manual review.
//
// ======================================================

if (validMissingSkills) {

  // A job may accept any one of several technologies.
  // Only explicitly recognized alternatives are checked.
  const alternativeGroups = [
    {
      skills: ["tensorflow", "pytorch", "jax"],
      jobPattern:
        /tensorflow\s+(?:or|\/)\s+pytorch\s+(?:or|\/)\s+jax|tensorflow\s+(?:or|\/)\s+pytorch\s+(?:or|\/)\s+jax/i
    }
  ];

  for (const missing of job.missing_skills) {

    const missingNormalized = normalize(missing);

    // Check whether the supposedly missing skill
    // is already verified in the candidate profile.
    const verifiedSkill = skillLookup.get(missingNormalized);

    if (verifiedSkill) {

      addError(
        `Verified candidate skill incorrectly marked as missing: ${missing}`
      );

      continue;
    }

    // Check supported OR groups without assuming that
    // every occurrence of "or" is an interchangeable
    // qualification.
    for (const group of alternativeGroups) {

      const mentionedAlternatives = group.skills.filter(
        skill => missingNormalized.includes(skill)
      );

      if (mentionedAlternatives.length === 0) {
        continue;
      }

      // Confirm that this alternative group actually
      // appears in the job description.
      const jobHasAlternativeGroup =
        group.jobPattern.test(jobText);

      if (!jobHasAlternativeGroup) {
        continue;
      }

      // Check whether a verified alternative satisfies
      // the employer's stated requirement.
      const verifiedAlternatives = group.skills.filter(
        skill => skillLookup.has(normalize(skill))
      );

      if (verifiedAlternatives.length > 0) {

        addError(
          `Already-satisfied alternative requirement incorrectly marked as missing: ${missing}`
        );

        break;
      }

    }

  }

}


// ======================================================
// 9. IDENTIFY MANDATORY JOB REQUIREMENTS
// ======================================================

// -----------------------------------------
// A. University enrollment
// -----------------------------------------
//
// Require evidence that the applicant must
// currently be enrolled.
//
// Avoid treating employees described as
// "Werkstudenten" as applicant requirements.
//
// -----------------------------------------

const enrollmentRequired =
  /\byou (?:are|must be|need to be) (?:currently )?enrolled\b|\bremain enrolled\b|\bcurrently enrolled\b|\benrolled at (?:a|an|the)\b|\bactive university enrollment\b|\bdu (?:bist|musst) (?:aktuell )?immatrikuliert\b|\bsie (?:sind|müssen) (?:aktuell )?immatrikuliert\b|\bimmatrikuliert sein\b|\beingeschrieben sein\b|\bdu bist (?:aktuell )?eingeschrieben\b|\bsie sind (?:aktuell )?eingeschrieben\b/i.test(
    requirementText
  );

// A thesis title alone is not proof of a
// mandatory enrollment requirement.

// -----------------------------------------
// B. Formal leadership — IMPROVED IN V3.3
// -----------------------------------------
//
// Detect explicit applicant leadership requirements.
//
// Do not treat references to the candidate's
// reporting manager as evidence that the
// applicant must have management experience.
//
// Examples that must NOT trigger leadershipRequired:
//
// "Reports to the Head of Platform Engineering"
// "Working with the Engineering Manager"
// "Collaborate with technical leaders"
//
// Examples that SHOULD trigger leadershipRequired:
//
// "Must have people management experience"
// "Experience leading an engineering team"
// "Leadership experience is required"
// "Führungserfahrung erforderlich"
//
// -----------------------------------------

const leadershipRequired = [

  // Explicit mandatory leadership experience.
  /\b(?:required|must have|need|minimum)\b.{0,80}\b(?:leadership experience|people management|team management)\b/,

  // Prior experience leading or managing teams.
  /\b(?:experience|proven track record)\s+(?:in|of|with)\s+(?:leading|managing)\s+(?:a |an |the )?(?:engineering |technical |data science |ml )?team\b/,

  // Leadership identified as required or essential.
  /\b(?:leadership experience|people management experience|team management experience)\s+(?:is|are)\s+(?:required|mandatory|essential)\b/,

  // German leadership requirements.
  /\bführungserfahrung\b/,

  /\bpersonalführung\b/,

  /\berfahrung\s+in\s+der\s+führung\s+(?:von\s+)?(?:teams|mitarbeitern|mitarbeitenden)\b/

].some(pattern => pattern.test(requirementText));

// -----------------------------------------
// C. Advanced German
// -----------------------------------------

const advancedGermanRequired =
  /verhandlungssicher.{0,25}deutsch|fluent german|fließend.{0,25}deutsch|deutsch.{0,25}\bc1\b|deutsch.{0,25}\bc2\b|german.{0,25}\bc1\b|german.{0,25}\bc2\b|muttersprachlich.{0,20}deutsch/.test(
    requirementText
  );

// ======================================================
// 10. EVALUATION TEXT
// ======================================================

const reason = normalize(job.fit_reason);

const missingText = validMissingSkills
  ? normalize(job.missing_skills.join(" "))
  : "";

const evaluationText = `${missingText} ${reason}`;

// ======================================================
// 11. CHECK UNSUPPORTED REQUIREMENT CLAIMS
// ======================================================

if (validMissingSkills) {

  for (const missing of job.missing_skills) {

    const claim = normalize(missing);

    if (
      /university enrollment|current enrollment|student enrollment/.test(claim) &&
      !enrollmentRequired
    ) {
      addError(
        "Unsupported university enrollment requirement"
      );
    }

    if (
      /formal leadership|formal team leadership|team leadership|people management/.test(claim) &&
      !leadershipRequired
    ) {
      addError(
        "Unsupported leadership requirement"
      );
    }

    if (
      /german proficiency|german c1|german c2|fluent german|higher than b1|verhandlungssicher/.test(claim) &&
      !advancedGermanRequired
    ) {
      addError(
        "Unsupported advanced German requirement"
      );
    }

  }

}

// ======================================================
// 12. CHECK OMITTED MANDATORY REQUIREMENTS
// ======================================================

// Enrollment gap must be acknowledged.

if (
  enrollmentRequired &&
  !/enroll|student|immatrikulier|eingeschrieben/.test(
    evaluationText
  )
) {
  addError(
    "Mandatory enrollment requirement not addressed"
  );
}

// Formal leadership gap must be acknowledged.

if (
  leadershipRequired &&
  !/leader|leadership|führung|management|teamleiter/.test(
    evaluationText
  )
) {
  addError(
    "Mandatory leadership requirement not addressed"
  );
}

// Advanced German requirement must be acknowledged.
//
// Candidate's verified German level is B1.

const advancedGermanGapAcknowledged =
  /german|deutsch|language|sprach/.test(
    evaluationText
  );

if (
  advancedGermanRequired &&
  !advancedGermanGapAcknowledged
) {
  addError(
    "Mandatory advanced German requirement not addressed"
  );
}

// ======================================================
// 13. CHECK SELECTED CONTRADICTIONS
// ======================================================

// Verified C++ does not establish C programming.

if (
  /\bpython\s*\/\s*c\b|\bprofessional c expertise\b|\bverified c programming\b/.test(
    reason
  )
) {
  addError(
    "Evaluation claims unverified C programming experience"
  );
}

// ======================================================
// 14. JOB RELEVANCE WARNINGS
// ======================================================
//
// Warnings do not invalidate the evaluation.
//
// ======================================================

const relevancePatterns = {

  "PyTorch": /pytorch/,
  "TensorFlow": /tensorflow/,
  "Scikit-learn": /scikit.learn/,
  "Qdrant": /qdrant/,
  "Vertex AI": /vertex ai/,
  "Docker": /docker|container/,
  "FastAPI": /fastapi/,
  "Git": /\bgit\b|version control/,
  "GitLab CI": /gitlab|ci\/cd/,
  "Speech Processing": /speech|audio|sprache|sprachverarbeitung/,
  "Multimodal Fusion": /multimodal/,
  "CUDA/HPC": /cuda|gpu|hpc/

};

for (const skill of normalizedMatchedSkills) {

  const pattern = relevancePatterns[skill];

  if (pattern && !pattern.test(jobText)) {
    addWarning(
      `Job relevance not explicitly confirmed: ${skill}`
    );
  }

}

// ======================================================
// 15. FINAL VALIDATION
// ======================================================

if (
  typeof job.fit_reason !== "string" ||
  !job.fit_reason.trim()
) {
  addError("Missing evaluation explanation");
}

// ======================================================
// 16. RETURN RESULT
// ======================================================

return {
  json: {

    ...job,

    // Reset validation status from previous executions.
    evaluation_status:
      errors.length === 0
        ? "validated"
        : "failed_validation",

    evaluation_error_message:
      errors.length === 0
        ? null
        : errors.join("; "),

    requires_manual_review:
      errors.length > 0,

    processed_at:
      new Date().toISOString(),

    normalized_matched_skills:
      normalizedMatchedSkills,

    unverified_matched_skills:
      unverifiedMatchedSkills,

    evaluation_valid:
      errors.length === 0,

    evaluation_errors:
      errors,

    evaluation_warnings:
      warnings,

    detected_requirements: {
      enrollment_required: enrollmentRequired,
      leadership_required: leadershipRequired,
      advanced_german_required: advancedGermanRequired
    },

    evaluation_checked_at:
      new Date().toISOString(),

    evaluation_validator_version:
      "v3.4"

  }
};

// Handle Invalid Evaluation
// Preserve failed evaluations for debugging.

const job = $input.item.json;

return {
  json: {
    ...job,

    evaluation_status: "failed_validation",

    evaluation_valid: false,

    evaluation_error_message:
      (job.evaluation_errors || []).join("; "),

    requires_manual_review: true,

    processed_at: new Date().toISOString()
  }
};

// Filter Valid Results
// Allow only structurally valid AI evaluations
// to proceed to downstream processing.

const items = $input.all();

const validJobs = items.filter(item => {

  const job = item.json;

  // Reject jobs that failed validation
  if (job.evaluation_valid !== true) {
    return false;
  }

  // Reject incomplete job records
  if (!job.external_id || !job.company || !job.title) {
    return false;
  }

  // Reject invalid fit scores
  if (
    typeof job.fit_score !== "number" ||
    !Number.isFinite(job.fit_score) ||
    job.fit_score < 0 ||
    job.fit_score > 100
  ) {
    return false;
  }

  // Reject jobs without a valid decision
  const validDecisions = [
    "strong_match",
    "possible_match",
    "weak_match",
    "not_relevant"
  ];

  if (!validDecisions.includes(job.decision)) {
    return false;
  }

  return true;

});

// Return only validated jobs
return validJobs;

