parameters.jsCode:
// =====================================================
// CHECK JOB ELIGIBILITY — VERSION 2
// =====================================================
//
// Purpose:
// Check mandatory job requirements before resume
// generation.
//
// Possible statuses:
// - eligible
// - needs_review
// - ineligible
//
// IMPORTANT:
// "eligible" means no blocking requirement was
// detected by these rules. It does not guarantee
// that every job requirement has been satisfied.
//
// This node preserves all existing job information.
// It does not modify the AI fit score.
//
// =====================================================


// =====================================================
// 1. VERIFIED CANDIDATE PROFILE
// =====================================================

const candidate = {

  // Master's degree completed October 2025.
  masters_completed: true,

  // Confirmed: not currently enrolled.
  currently_enrolled: false,

  // Exact professional industry experience
  // has not been independently established.
  verified_industry_years: null,

  // Confirmed: no formal team-lead or
  // people-management experience.
  formal_leadership_experience: false,

  // Language proficiency.
  german_level: "B1",
  english_level: "business_fluent",

  // Current country of residence.
  residence_country: "Germany"

};


// =====================================================
// 2. RECEIVE INPUT
// =====================================================

const items = $input.all();


// =====================================================
// 3. PROCESS EACH JOB
// =====================================================

return items.map(item => {

  const job = item.json;

  const title = String(job.title || "");

  const description = String(
    job.clean_description ||
    job.description ||
    ""
  );

  // Remove HTML formatting where necessary.
  const cleanText = description
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/\s+/g, " ")
    .trim();

  const fullText = `${title} ${cleanText}`;
  // Remove explicitly excluded requirements from
  // mandatory qualification checks.
  //
  // Preserve fullText for other uses.

  const requirementText = `${title} ${
    cleanText.split(/\bNOT REQUIRED\s*:/i)[0]
  }`;

  const reasons = [];

  let eligibilityStatus = "eligible";


  // ===================================================
  // 4. HELPER FUNCTION
  // ===================================================

  function addFinding(status, reason) {

    if (!reasons.includes(reason)) {
      reasons.push(reason);
    }

    // Ineligible has the highest priority.
    if (status === "ineligible") {
      eligibilityStatus = "ineligible";
      return;
    }

    // Needs review has priority over eligible.
    if (
      status === "needs_review" &&
      eligibilityStatus !== "ineligible"
    ) {
      eligibilityStatus = "needs_review";
    }

  }


  // ===================================================
  // 5. UNIVERSITY ENROLLMENT
  // ===================================================

  const thesisRole =
    /\b(bachelor'?s?|master'?s?)\s*(\/|or|&)\s*(bachelor'?s?|master'?s?)\s*thesis\b/i
      .test(fullText) ||
    /\b(master'?s?|bachelor'?s?)\s*thesis\b/i
      .test(fullText) ||
    /\babschlussarbeit\b|\bmasterarbeit\b|\bbachelorarbeit\b/i
      .test(fullText);

  const explicitEnrollment =
    /\bcurrently enrolled\b/i.test(fullText) ||
    /\bremain enrolled\b/i.test(fullText) ||
    /\byou are enrolled\b/i.test(fullText) ||
    /\benrolled at a .*university\b/i.test(fullText) ||
    /\bimmatrikuliert\b/i.test(fullText) ||
    /\beingeschrieben\b/i.test(fullText);

  if (thesisRole && explicitEnrollment) {

    if (candidate.currently_enrolled === false) {

      addFinding(
        "ineligible",
        "The thesis position requires active university enrollment, but the candidate is not currently enrolled."
      );

    } else {

      addFinding(
        "needs_review",
        "Confirm continued university enrollment and academic supervision requirements."
      );

    }

  } else if (thesisRole) {

    addFinding(
      "needs_review",
      "This is a thesis position. Confirm whether current university enrollment is mandatory."
    );

  } else if (explicitEnrollment) {

    addFinding(
      "needs_review",
      "The vacancy mentions university enrollment. Confirm whether it is a mandatory requirement."
    );

  }


  // ===================================================
  // 6. GERMAN LANGUAGE REQUIREMENTS
  // ===================================================

  const advancedGermanRequired =
    /\bverhandlungssicher(?:es|e|en|er)?\s+deutsch\b/i
      .test(requirementText) ||
    /\bdeutsch(?:kenntnisse)?\s*(?:auf\s*)?c1\b/i
      .test(requirementText) ||
    /\bgerman\s*(?:at\s*)?c1\b/i
      .test(requirementText) ||
    /\bfluent\s+(?:in\s+)?german\b/i
      .test(requirementText) ||
    /\bfließend(?:es|e|en|er)?\s+deutsch\b/i
      .test(requirementText);

  if (advancedGermanRequired) {

    addFinding(
      "needs_review",
      "The job appears to require fluent or C1-level German. The candidate's verified German level is B1."
    );

  }


  // ===================================================
  // 7. PROFESSIONAL EXPERIENCE REQUIREMENTS
  // ===================================================

  const experiencePatterns = [

    /\b(\d+)\s*\+?\s*(?:years?|yrs?)\s+(?:of\s+)?(?:professional|industry|commercial|work)\s+experience\b/i,

    /\b(?:minimum|at least)\s+(\d+)\s*(?:years?|yrs?)\s+(?:of\s+)?(?:professional|industry|commercial|work)\s+experience\b/i,

    /\b(\d+)\s*\+?\s*jahre\s+berufserfahrung\b/i

  ];

  let requiredYears = null;

  for (const pattern of experiencePatterns) {

    const match = requirementText.match(pattern);

    if (match) {

      requiredYears = Number(match[1]);

      break;

    }

  }

  if (requiredYears !== null) {

    if (candidate.verified_industry_years === null) {

      addFinding(
        "needs_review",
        `The position requires ${requiredYears}+ years of professional experience. The candidate's verified industry experience needs confirmation.`
      );

    } else if (
      candidate.verified_industry_years < requiredYears
    ) {

      addFinding(
        "ineligible",
        `The position requires ${requiredYears}+ years of professional experience, exceeding the candidate's verified experience.`
      );

    }

  }


  // ===================================================
  // 8. FORMAL TEAM LEADERSHIP REQUIREMENTS
  // ===================================================

  // Detect leadership-focused titles.
  //
  // IMPORTANT:
  // We do not flag ordinary descriptions mentioning
  // teamwork, collaboration, or ownership.

  const leadershipTitle =
    /\bteamleiter(?:in)?\b/i.test(title) ||
    /\bteamleitung\b/i.test(title) ||
    /\bteam\s+lead(?:er)?\b/i.test(title) ||
    /\bhead\s+of\b/i.test(title) ||
    /\bengineering\s+manager\b/i.test(title) ||
    /\bdata\s+science\s+manager\b/i.test(title) ||
    /\b(?:people|team)\s+manager\b/i.test(title);

  // Detect explicit prior leadership requirements
  // in English or German job descriptions.

  const explicitLeadershipRequirement =
    /\b(?:prior|previous|proven)\s+(?:team\s+)?(?:leadership|management)\s+experience\b/i
      .test(cleanText) ||

    /\b(?:erste|mehrjährige|einschlägige)\s+führungserfahrung\b/i
      .test(cleanText) ||

    /\bführungserfahrung\b/i
      .test(cleanText) ||

    /\b(?:experience\s+(?:in|with)\s+)?managing\s+(?:a\s+)?team\b/i
      .test(cleanText);

  // Employment type can also indicate a
  // formal leadership position.

  const employmentTypes = Array.isArray(job.employment_types)
    ? job.employment_types
    : [];

  const leadershipEmploymentType =
    employmentTypes.some(type =>

      /\bteamleitung\b|\bteamleiter\b/i.test(
        String(type)
      )

    );

  const leadershipRole =
    leadershipTitle ||
    explicitLeadershipRequirement ||
    leadershipEmploymentType;

  if (
    leadershipRole &&
    candidate.formal_leadership_experience === false
  ) {

    addFinding(
      "needs_review",
      "This position appears to require formal team leadership or people-management experience. The candidate has no verified formal leadership experience."
    );

  }


  // ===================================================
  // 9. LOCATION REQUIREMENTS
  // ===================================================

  const requiresGermanResidence =
    /\bwohn(?:sitz|ort)\s+in\s+deutschland\b/i
      .test(fullText) ||
    /\bmust\s+(?:be\s+)?(?:based|reside)\s+in\s+germany\b/i
      .test(fullText);

  if (
    requiresGermanResidence &&
    candidate.residence_country !== "Germany"
  ) {

    addFinding(
      "ineligible",
      "The position requires residence in Germany."
    );

  }


  // ===================================================
  // 10. RETURN RESULT
  // ===================================================

  return {

    json: {

      // Preserve original job information.
      ...job,

      // Eligibility decision.
      eligibility_status: eligibilityStatus,

      // Explain why review/rejection is required.
      eligibility_reasons: reasons,

      // Metadata.
      eligibility_checked: true,

      eligibility_check_type: "rule_based_v2",

      // Flag uncertain cases for manual review.
      eligibility_review_required:
        eligibilityStatus === "needs_review",

      // Record whether leadership was detected.
      leadership_requirement_detected:
        leadershipRole

    }

  };

});
